export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = 9.8;
  const t = time;

  const height = launchSpeed * t - 0.5 * gravity * t * t;
  const velocity = launchSpeed - gravity * t;

  const topTime = launchSpeed / gravity;
  const topHeight = (launchSpeed * launchSpeed) / (2 * gravity);

  // Map physics to screen coordinates (y down)
  // Frame size: 640 x 420
  // Let base be at y = 320, scale = 80 pixels per meter
  const baseY = 320;
  const scale = 80;
  const ballY = baseY - height * scale;
  const ballX = 320;

  // Motion state text for callout
  let motionStateText = "Moving up";
  if (Math.abs(velocity) < 0.05) {
    motionStateText = "Still for an instant";
  } else if (velocity < 0) {
    motionStateText = "Moving down";
  }

  const objects = [];

  // Lane
  objects.push(sdk.panel({
    x: 40, y: 40, w: 560, h: 360,
    title: "Vertical Toss",
    state: motionStateText,
    id: "lane.toss"
  }));

  // Axis
  objects.push(sdk.axis("axis.y", {
    x: 160, y: 320,
    length: 240,
    orientation: "y",
    min: 0,
    max: 3,
    label: "Height",
    unit: "m"
  }));

  // Launch height guide mark
  objects.push(sdk.groundMark("mark.launch", ballX, baseY, 60, "Launch"));

  // Ball
  objects.push(sdk.circle("ball.toss", ballX, ballY, 28, {
    role: "output"
  }));

  // Gravity vector (always down)
  objects.push(sdk.vector("vec.a", {
    x: ballX + 20,
    y: ballY
  }, {
    value: gravity,
    direction: "down"
  }, {
    scale: 4,
    minLength: 16,
    label: "a"
  }));

  // Motion vector (velocity), omitted if very close to zero
  if (Math.abs(velocity) >= 0.05) {
    objects.push(sdk.vector("vec.v", {
      x: ballX - 20,
      y: ballY
    }, {
      value: Math.abs(velocity),
      direction: velocity > 0 ? "up" : "down"
    }, {
      scale: 12,
      minLength: 16,
      label: "v"
    }));
  }

  // Callout beside the ball
  const calloutLines = [
    motionStateText,
    "Gravity pulls down"
  ];
  objects.push(sdk.callout(ballX + 45, ballY - 20, calloutLines, {
    id: "callout.toss"
  }));

  const motionStateVal = motionStateText;
  const gravityStateVal = "Gravity pulls down";

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "motionState", value: motionStateVal },
        { id: "gravityState", value: gravityStateVal }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime: topTime,
      apexHeight: topHeight,
      velocity,
      height
    }
  };
}
